class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses sync-over-async for Cosmos which can deadlock.
        // Use async methods instead.
        RunAsync(context).GetAwaiter().GetResult();
    }

    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }

    // Breaking change 5: Raw SQL queries using "Discriminator" property still work
    // but only because we configured HasDiscriminator("Discriminator") above.
    // Without that config, you'd need to change queries to use "$type" instead:
    //   Before: SELECT * FROM c WHERE c.Discriminator = 'Blog'
    //   After (without compat config): SELECT * FROM c WHERE c["$type"] = 'Blog'
}

